### __tests__/acceptance/receiptEntryScreen.test.ts
```ts
import React from 'react';
import { render, screen } from '@testing-library/react-native';
import { Provider as PaperProvider } from 'react-native-paper';
import { theme } from '../../src/theme';
import ReceiptEntryScreen from '../../src/screens/ReceiptEntryScreen';

// Mock the OCR library to indicate that scanning is not supported.
jest.mock('expo-text-extractor', () => ({
  isSupported: false,
  extractTextFromImage: jest.fn(),
}));

// Helper that renders the screen with the providers it needs.
function renderReceiptEntryScreen() {
  // Minimal navigation mock – the screen only uses navigate/goBack.
  const navigation = { navigate: jest.fn(), goBack: jest.fn() } as any;
  // Minimal route mock – the screen may read route.params but none are required.
  const route = { key: 'ReceiptEntry', name: 'ReceiptEntry', params: {} } as any;
  return render(
    <PaperProvider theme={theme}>
      <ReceiptEntryScreen navigation={navigation} route={route} />
    </PaperProvider>,
  );
}

describe('ReceiptEntryScreen UI layout', () => {
  test('screen title appears only once (in the header)', () => {
    renderReceiptEntryScreen();

    // The title “Add receipt” should be rendered exactly once.
    const titles = screen.getAllByText('Add receipt');
    expect(titles).toHaveLength(1);
  });

  test('date picker icon is rendered inside the Date field', () => {
    renderReceiptEntryScreen();

    // The date field’s icon is given a dedicated testID.
    const dateIcon = screen.getByTestId('date-picker-icon');
    expect(dateIcon).toBeTruthy();
  });

  test('form fields have standard spacing (no empty gaps larger than 12 dp)', () => {
    renderReceiptEntryScreen();

    // Each input wrapper is given a testID of the form “field-wrapper‑<name>”.
    const fieldIds = ['amount', 'date', 'category', 'type', 'notes'];
    fieldIds.forEach((id) => {
      const wrapper = screen.getByTestId(`field-wrapper-${id}`);
      // The wrapper should use the standard vertical rhythm: marginBottom = 12.
      expect(wrapper).toHaveStyle({ marginBottom: 12 });
    });
  });

  test('Scan receipt button is not shown when OCR scanning is unavailable', () => {
    renderReceiptEntryScreen();

    // The button is hidden when `expo-text-extractor.isSupported` is false.
    const scanButton = screen.queryByTestId('scan-receipt-button');
    expect(scanButton).toBeNull();
  });
});
```

