import fs from 'fs';
import path from 'path';

const sourcePath = path.resolve(
  __dirname,
  '../../src/screens/ReceiptEntryScreen.tsx',
);
const source = fs.readFileSync(sourcePath, 'utf8');

describe('ReceiptEntryScreen UI conventions (source‑level checks)', () => {
  test('screen title “Add receipt” appears exactly once (in the header only)', () => {
    // The title string should only be defined once in the source file.
    const matches = source.match(/Add receipt/g);
    const count = matches ? matches.length : 0;
    expect(count).toBe(1);
  });

  test('date picker icon is embedded inside the Date field', () => {
    // We expose the date‑picker icon via a testID “date-picker-icon”.
    expect(source).toMatch(/testID\s*=\s*['"]date-picker-icon['"]/);
  });

  test('no vertical gaps larger than the standard 12 dp spacing between fields', () => {
    // Extract every marginBottom numeric value from the file.
    const marginRegex = /marginBottom\s*:\s*(\d+)/g;
    const margins: number[] = [];
    let match: RegExpExecArray | null;
    while ((match = marginRegex.exec(source)) !== null) {
      margins.push(parseInt(match[1], 10));
    }
    // If the file defines any marginBottom, the largest must be ≤ 12.
    if (margins.length > 0) {
      const max = Math.max(...margins);
      expect(max).toBeLessThanOrEqual(12);
    } else {
      // If the file does not specify any marginBottom, the test fails because spacing is not explicit.
      fail('No marginBottom values found – cannot verify standard spacing.');
    }
  });
});
````

