import React from 'react';
import { render } from '@testing-library/react-native';
import ReceiptEntryScreen from '../../src/screens/ReceiptEntryScreen';

/**
 * Recursively walk a React test‑renderer JSON tree and collect any
 * numeric `marginBottom` values found in style props.
 */
function collectMargins(node: any, out: number[]) {
  if (!node) return;

  const styleProp = node.props?.style;
  if (styleProp) {
    const styles = Array.isArray(styleProp) ? styleProp : [styleProp];
    for (const s of styles) {
      if (s && typeof s.marginBottom === 'number') {
        out.push(s.marginBottom);
      }
    }
  }

  if (node.children) {
    node.children.forEach((child: any) => {
      if (typeof child === 'object') {
        collectMargins(child, out);
      }
    });
  }
}

/**
 * Helper that renders the screen with the minimal navigation mock required
 * for the component to mount without crashing.
 */
function renderScreen() {
  const navigationMock = { setOptions: jest.fn() };
  // Some screens also accept a `route` prop; provide an empty stub just in case.
  const routeMock = {};
  return render(
    <ReceiptEntryScreen navigation={navigationMock as any} route={routeMock as any} />
  );
}

describe('ReceiptEntryScreen UI conventions', () => {
  test('screen title "Add receipt" appears exactly once in the UI', () => {
    const { getAllByText } = renderScreen();
    const titleElements = getAllByText('Add receipt');
    expect(titleElements).toHaveLength(1);
  });

  test('date picker icon is embedded inside the Date field', () => {
    const { getByTestId } = renderScreen();
    // The date‑picker icon should expose the testID `date-picker-icon`.
    expect(getByTestId('date-picker-icon')).toBeTruthy();
  });

  test('no vertical gaps larger than the standard 12 dp spacing between fields', () => {
    const { toJSON } = renderScreen();
    const tree = toJSON();

    const margins: number[] = [];
    collectMargins(tree, margins);

    // If any explicit `marginBottom` values are present, the largest must be ≤ 12.
    // When no explicit margins exist (e.g., spacing via flex or theme constants),
    // the test passes because there is no evidence of a too‑large gap.
    if (margins.length > 0) {
      const max = Math.max(...margins);
      expect(max).toBeLessThanOrEqual(12);
    } else {
      expect(true).toBe(true);
    }
  });
});
```

